/// <summary>Which slot the clock says should be on right now, and what follows it</summary>
public sealed record ScheduleNow
{
    /// <summary>What time it is on the station's own clock, in the same zone-naive `YYYY-MM-DD HH:mm:ss` shape as a block's ends. It is here so a caller can say how much of the block is left without knowing the station's timezone: subtracting two readings taken in one frame is arithmetic, deriving one is not</summary>
